{"code": "const content = `const fs = require("fs");
const path = require("path");

function readAsar(file) {
  const fd = fs.openSync(file, "r");
  const sizeBuf = Buffer.alloc(16);
  fs.readSync(fd, sizeBuf, 0, 16, 0);
  const headerPickleSize = sizeBuf.readUInt32LE(0);
  const jsonSize = sizeBuf.readUInt32LE(4);
  const jsonBuf = Buffer.alloc(headerPickleSize);
  fs.readSync(fd, jsonBuf, 0, headerPickleSize, 8);
  const header = JSON.parse(jsonBuf.slice(0, jsonSize).toString("utf8"));
  const baseOffset = 8 + headerPickleSize;
  return { fd, header, baseOffset, fileSize: fs.statSync(file).size };
}

function walk(node, prefix, out) {
  for (const [name, entry] of Object.entries(node.files || {})) {
    const full = prefix + "/" + name;
    if (entry.files) walk(entry, full, out);
    else out.push({ path: full, size: entry.size, offset: entry.offset, unpacked: !!entry.unpacked, executable: !!entry.executable });
  }
}

const file = process.argv[2];
const outDir = process.argv[3];
const filter = process.argv[4] ? new RegExp(process.argv[4]) : null;
const { fd, header, baseOffset } = readAsar(file);
const list = [];
walk(header, "", list);
console.log("entries:", list.length);
if (!outDir) {
  for (const e of list) console.log(e.size.toString().padStart(9), e.path);
} else {
  for (const e of list) {
    if (filter && !filter.test(e.path)) continue;
    const dest = path.join(outDir, e.path);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    if (e.unpacked) { console.log("UNPACKED (skip)", e.path); continue; }
    const buf = Buffer.alloc(e.size);
    fs.readSync(fd, buf, 0, e.size, baseOffset + Number(e.offset));
    fs.writeFileSync(dest, buf);
  }
  console.log("extracted to", outDir);
}
fs.closeSync(fd);
`;
