{"code": "const content = `const fs = require("fs");
const path = require("path");

function readAsar(file) {
  const fd = fs.openSync(file, "r");
  const head = Buffer.alloc(16);
  fs.readSync(fd, head, 0, 16, 0);
  const pickleSize = head.readUInt32LE(4);
  const jsonSize = head.readUInt32LE(8);
  const jsonBuf = Buffer.alloc(jsonSize);
  fs.readSync(fd, jsonBuf, 0, jsonSize, 12);
  const header = JSON.parse(jsonBuf.toString("utf8"));
  return { fd, header, baseOffset: 8 + pickleSize };
}

function walk(node, prefix, out) {
  for (const [name, entry] of Object.entries(node.files || {})) {
    const full = prefix + "/" + name;
    if (entry.files) walk(entry, full, out);
    else out.push({ path: full, size: Number(entry.size), offset: Number(entry.offset), unpacked: !!entry.unpacked });
  }
}

const file = process.argv[2];
const outList = process.argv[3];
const { fd, header, baseOffset } = readAsar(file);
const list = [];
walk(header, "", list);
const lines = list.map(e => e.size + "\\t" + e.path + (e.unpacked ? "\\t(UNPACKED)" : ""));
fs.writeFileSync(outList, lines.join("\\n") + "\\n");
const top = new Map();
for (const e of list) {
  const seg = e.path.split("/")[1] || "";
  top.set(seg, (top.get(seg) || 0) + 1);
}
for (const [k, v] of [...top.entries()].sort()) process.stdout.write(k + ": " + v + "\\n");
process.stdout.write("TOTAL " + list.length + "\\nBASE " + baseOffset + "\\n");
fs.closeSync(fd);
`;
