{"code": "await tools.write({
  file_path: "/Users/oyamahappa/Documents/Agent/DSH/work/qq-anti-recall/analysis/cdp-dump.js",
  content: `const fs = require("fs");
const path = require("path");

const endpoint = process.argv[2];
const outDir = process.argv[3];
fs.mkdirSync(outDir, { recursive: true });

async function main() {
  const listRes = await fetch("http://" + endpoint + "/json/list");
  const targets = await listRes.json();
  console.log("targets:", targets.map(t => t.type + " " + (t.title || "") + " " + (t.url || "").slice(0, 60)).join(" | "));
  const target = targets.find(t => t.webSocketDebuggerUrl && (t.type === "page" || t.type === "node" || t.type === "renderer"));
  if (!target) throw new Error("no attachable target");
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  const scripts = new Map();
  ws.addEventListener("message", ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
      return;
    }
    if (msg.method === "Debugger.scriptParsed") {
      const p = msg.params;
      scripts.set(p.scriptId, { url: p.url, length: p.length || 0 });
    }
  });
  const send = (method, params) => new Promise((res, rej) => {
    const myId = ++id;
    pending.set(myId, res);
    ws.send(JSON.stringify({ id: myId, method, params: params || {} }));
  });
  await new Promise((res, rej) => {
    ws.addEventListener("open", res);
    ws.addEventListener("error", rej);
  });
  await send("Debugger.enable");
  await new Promise(r => setTimeout(r, 1500));
  console.log("scripts seen:", scripts.size);
  let dumped = 0;
  const index = [];
  for (const [scriptId, meta] of scripts) {
    if (!meta.url || meta.url.startsWith("devtools://")) continue;
    const res = await send("Debugger.getScriptSource", { scriptId });
    const src = res.result && res.result.scriptSource;
    if (!src) continue;
    const safe = meta.url.replace(/[^a-zA-Z0-9._-]/g, "_").slice(-150) + "-" + scriptId + ".js";
    fs.writeFileSync(path.join(outDir, safe), src);
    index.push({ scriptId, url: meta.url, bytes: src.length, file: safe });
    dumped++;
  }
  fs.writeFileSync(path.join(outDir, "_index.json"), JSON.stringify(index, null, 2));
  console.log("dumped", dumped);
  ws.close();
}

main().catch(e => { console.error("ERR", e.message); process.exit(1); });
`});
console.log("written");", "description": "Write CDP script source dumper"}

