function summarize(v) {
  try {
    if (typeof v === "string") return JSON.stringify(v.length > 400 ? v.slice(0, 400) + "..." : v);
    if (v === null || v === undefined || typeof v !== "object") return String(v);
    const s = JSON.stringify(v);
    return s.length > 600 ? s.slice(0, 600) + "..." : s;
  } catch (e) { return "<unserializable>"; }
}

let patched = false;
function patchWebContents() {
  if (patched) return true;
  const all = electron.webContents.getAllWebContents();
  if (!all.length) return false;
  const proto = Object.getPrototypeOf(all[0]);
  for (const name of ["send", "postMessage"]) {
    const original = proto[name];
    if (typeof original !== "function") { log("missing proto." + name); continue; }
    proto[name] = function (...args) {
      const ch = String(args[0]);
      const key = name + ":" + ch;
      const n = (counts.get(key) || 0) + 1;
      counts.set(key, n);
      if (n <= 2) log("SEND " + key + " :: " + args.slice(1).map(summarize).join(" | ").slice(0, 700));
      return original.apply(this, args);
    };
    log("patched proto." + name);
  }
  patched = true;
  return true;
}
const tick = setInterval(patchWebContents, 500);
setTimeout(() => clearInterval(tick), 60000);

function runEval(code) {
  const all = electron.webContents.getAllWebContents();
  const results = [];
  let pending = all.length;
  for (const wc of all) {
    const url = (wc.getURL() || "").slice(0, 60);
