const dev = `const fs = require("fs");
const path = require("path");
const electron = require("electron");

const DIR = global.__qqPluginDir || path.join(process.env.HOME, "Library/Logs/QQPlugin");
const CAP = path.join(DIR, "captures");
try { fs.mkdirSync(CAP, { recursive: true }); } catch (e) {}
const log = global.__qqPluginLog || function () {};

function summarize(v) {
  if (typeof v === "string") return v.length > 2000 ? v.slice(0, 2000) + "..." : v;
  try { const s = JSON.stringify(v); return s && s.length > 3000 ? s.slice(0, 3000) + "..." : String(s); } catch (e) { return "<unserializable>"; }
}

let seq = 0;
function dumpCapture(channel, args) {
  seq += 1;
  const payload = args[1];
  const cmdName = payload && payload.cmdName ? String(payload.cmdName) : "unknown";
  const slug = cmdName.replace(/[^a-zA-Z0-9._-]/g, "_").slice(0, 80);
  const file = path.join(CAP, String(Date.now()) + "_" + seq + "_" + slug + ".json");
  try {
    fs.writeFileSync(file, JSON.stringify({ channel: channel, cmdName: cmdName, meta: args[0], payload: payload }, null, 2).slice(0, 400000));
  } catch (e) { log("capture write error " + e.message); }
}

const interestingRe = /(Listener\\/on|Recall|Revoke|recall|revoke|MsgInfo|onRecvMsg|onMsg)/;
const seen = new Map();
let patched = false;

function patchWebContents() {
  if (patched) return true;
  const all = electron.webContents.getAllWebContents();
  if (!all.length) return false;
  const proto = Object.getPrototypeOf(all[0]);
  for (const name of ["send", "postMessage"]) {
    const original = proto[name];
    if (typeof original !== "function") continue;
    proto[name] = function (...args) {
      const ch = String(args[0]);
      let cmdName = "";
      try { cmdName = args[1] && args[1].cmdName ? String(args[1].cmdName) : ""; } catch (e) {}
      if (cmdName) {
        const key = ch + "|" + cmdName;
        const n = (seen.get(key) || 0) + 1;
        seen.set(key, n);
        if (interestingRe.test(cmdName) && n <= 40) dumpCapture(ch, args);
        if (n <= 1) log("SEND " + ch + " " + cmdName);
      }
      return original.apply(this, args);
    };
  }
  patched = true;
  log("patched WebContents prototype send/postMessage");
  return true;
}
const tick = setInterval(patchWebContents, 300);
setTimeout(() => clearInterval(tick), 1800000);

function windows() { return electron.webContents.getAllWebContents(); }
function mainWin() { return windows().find(w => (w.getURL() || "").includes("#/main")) || null; }
function loginWin() { return windows().find(w => (w.getURL() || "").includes("login.html")) || null; }

const AUTOTEST = fs.readFileSync(path.join(__dirname, "autotest.js"), "utf8");
let autoState = "idle";

async function autoRun() {
  const login = loginWin();
  if (login) {
    try {
      const r = await login.executeJavaScript("(() => { const b=[...document.querySelectorAll('button')].find(e=>(e.textContent||'').trim()==='登录'); if(!b) return 'nobtn'; b.click(); return 'clicked'; })()", true);
      if (r === "clicked") { log("AUTO login clicked"); autoState = "logged-in-wait"; }
    } catch (e) { log("AUTO login err " + e.message); }
    return;
  }
  const main = mainWin();
  if (!main) return;
  if (autoState === "done") return;
  autoState = "running";
  try {
    const res = await main.executeJavaScript(AUTOTEST, true);
    log("AUTO result " + summarize(res).slice(0, 900));
    autoState = "done";
  } catch (e) {
    log("AUTO eval err " + e.message);
    autoState = "retry";
  }
}

setInterval(() => {
  if (!fs.existsSync(path.join(DIR, "autotest.on"))) return;
  if (autoState === "running") return;
  autoRun().catch(e => log("AUTO outer err " + e.message));
}, 4000);

function runEval(code) {
  const wc = mainWin() || loginWin() || windows()[0];
  if (!wc) { try { fs.writeFileSync(path.join(DIR, "out"), "no window"); } catch (e) {} return; }
  const url = (wc.getURL() || "").slice(0, 100);
  wc.executeJavaScript(code, true).then(v => {
    try { fs.writeFileSync(path.join(DIR, "out"), url + " => " + summarize(v)); } catch (e) {}
  }).catch(e => {
    try { fs.writeFileSync(path.join(DIR, "out"), url + " ERR " + e.message); } catch (e2) {}
  });
}

async function runMainEval(code) {
  const target = path.join(DIR, "mout");
  try {
    const fn = new Function("require", "electron", "return (async () => { " + code + " })()");
    const v = await fn(require, electron);
    fs.writeFileSync(target, summarize(v));
  } catch (e) {
    try { fs.writeFileSync(target, "ERR " + e.message); } catch (e2) {}
  }
}

setInterval(() => {
  for (const [name, fn] of [["cmd", runEval], ["mcmd", runMainEval]]) {
    const p = path.join(DIR, name);
    let body;
    try { body = fs.readFileSync(p, "utf8"); } catch (e) { continue; }
    if (!body.trim()) continue;
    try { fs.unlinkSync(p); } catch (e) {}
    fn(body);
  }
}, 500);
`;
