  }
  return parts.join("").trim();
}

function chatKeyOf(msg) {
  return String(msg.chatId || msg.peerUid || msg.channelId || msg.guildId || "");
}

function msgKeyOf(msg) {
  const id = msg.msgId || msg.msgSeq || msg.messageId;
  return id === undefined || id === null ? "" : String(id);
}

function isMsgLike(node) {
  if (!node || typeof node !== "object" || Array.isArray(node)) return false;
  return Array.isArray(node.elements) && (node.msgId !== undefined || node.msgSeq !== undefined || node.messageId !== undefined);
}

function collectMsgLists(root, found, depth) {
  if (!root || typeof root !== "object" || depth > 8 || found.length > 4000) return found;
  if (Array.isArray(root)) {
    if (root.length && isMsgLike(root[0])) found.push(root);
    for (const item of root) collectMsgLists(item, found, depth + 1);
    return found;
  }
  for (const key of Object.keys(root)) {
    const v = root[key];
    if (Array.isArray(v) && v.length && isMsgLike(v[0])) found.push(v);
    else if (v && typeof v === "object") collectMsgLists(v, found, depth + 1);
  }
  return found;
}

function remember(msg, text) {
  const id = msgKeyOf(msg);
  const chat = chatKeyOf(msg);
  const entry = { id: id, chat: chat, sender: String(msg.senderUid || msg.senderUin || ""), time: Number(msg.msgTime || 0) || Date.now(), text: text, elements: msg.elements, msgType: msg.msgType };
  if (id) cacheById.set(chat + "|" + id, entry);
  let list = cacheByChat.get(chat);
  if (!list) { list = []; cacheByChat.set(chat, list); }
  list.push(entry);
  if (list.length > MAX_CACHED_PER_CHAT) list.splice(0, list.length - MAX_CACHED_PER_CHAT);
  while (cacheByChat.size > MAX_CACHED_CHATS) cacheByChat.delete(cacheByChat.keys().next().value);
}

function findRecallSource(msg) {
  const chat = chatKeyOf(msg);
  const sender = String(msg.senderUid || msg.senderUin || "");
  const list = cacheByChat.get(chat);
  if (!list) return null;
  for (let i = list.length - 1; i >= 0; i--) {
    const e = list[i];
    if (e.text && (!sender || e.sender === sender)) return e;
  }
  for (let i = list.length - 1; i >= 0; i--) if (list[i].text) return list[i];
  return null;
}

function rewriteRecallTip(msg, text) {
  const source = findRecallSource(msg);
  if (!source) { log("TIP without cache chat=" + chatKeyOf(msg) + " text=" + text.slice(0, 40)); return false; }
  const replacement = text.replace(RECALL_TIP, "撤回了一条消息（已拦截，原文：" + source.text.slice(0, 400) + "）");
  const el = (msg.elements || []).find(e => e && e.textElement && typeof e.textElement.content === "string" && e.textElement.content === text);
  if (!el) return false;
  el.textElement.content = replacement;
  log("REWRITE_TIP chat=" + chatKeyOf(msg) + " original=" + source.text.slice(0, 80));
  return true;
}

function restoreRevoked(msg) {
  const id = msgKeyOf(msg);
  const chat = chatKeyOf(msg);
  const cached = id ? cacheById.get(chat + "|" + id) : null;
  if (!cached || !cached.text) return false;
  const current = extractText(msg);
  const emptyNow = !current || RECALL_TIP.test(current);
  if (!emptyNow) return false;
  msg.elements = cached.elements;
  if (cached.msgType !== undefined) msg.msgType = cached.msgType;
  log("RESTORE_MSG chat=" + chat + " id=" + id + " text=" + cached.text.slice(0, 80));
  return true;
}

let stats = { seen: 0, tips: 0, restored: 0 };

function processArgs(channel, args) {
  if (!/RM_IPCFROM_MAIN/.test(channel)) return;
  const payload = args[1];
  if (!payload || typeof payload !== "object") return;
  const lists = collectMsgLists(payload, [], 0);
  if (!lists.length) return;
  stats.seen += 1;
  for (const list of lists) {
    for (const msg of list) {
      if (!isMsgLike(msg)) continue;
      const text = extractText(msg);
      if (text && RECALL_TIP.test(text) && text.length < 200) {
        stats.tips += 1;
        if (!rewriteRecallTip(msg, text)) remember(msg, "");
        continue;
      }
      if (restoreRevoked(msg)) { stats.restored += 1; continue; }
      if (text) remember(msg, text);
    }
  }
}

module.exports = { processArgs: processArgs, stats: function () { return stats; } };
