  const item = all.find(e => (e.getAttribute("class") || "").includes("recent-contact-item") && (e.textContent || "").includes("OyamaHappa"));
  if (item) { item.click(); out.steps.push("clicked contact"); } else out.steps.push("no contact");
  await sleep(2500);
  const nodes = [];
  walk(document, el => nodes.push(el));
  const list = nodes.filter(e => { const c = e.getAttribute("class") || ""; return c.includes("message-list") || c.includes("msg-list") || c.includes("q-scroll-view") && (e.textContent || "").includes("撤回"); });
  out.containers = list.slice(0, 6).map(e => (e.tagName + "|" + (e.getAttribute("class") || "").slice(0, 60) + "|children=" + e.children.length));
  const tipEl = nodes.find(e => e.children.length === 0 && (e.textContent || "").trim().includes("撤回了一条消息"));
  if (tipEl) {
    out.tipChain = [];
    let n = tipEl;
    for (let i = 0; i < 10 && n; i++) {
      out.tipChain.push(n.tagName + "|" + String(n.getAttribute("class") || "").slice(0, 50) + "|" + [...n.attributes].map(a => a.name + "=" + String(a.value).slice(0, 20)).slice(0, 8).join(","));
      n = n.parentElement;
    }
  } else out.tipChain = "no tip";
  const rowSel = nodes.filter(e => { const c = e.getAttribute("class") || ""; return c.includes("message-item") || c.includes("msg-item") || c.includes("message__") ; });
  out.rowClasses = [...new Set(rowSel.map(e => (e.getAttribute("class") || "").slice(0, 60)))].slice(0, 12);
