  if (cached.subMsgType !== undefined) msg.subMsgType = cached.subMsgType;
  log("RESTORE_MSG peer=" + peerOf(msg) + " id=" + idOf(msg) + " text=" + String(cached.text).slice(0, 60));
  return true;
}

function rewriteTip(msg) {
  const peer = peerOf(msg);
  const sender = String(msg.senderUid || "");
  const cached = recentTextFor(peer, sender) || recentTextFor(peer, "");
  const elements = Array.isArray(msg.elements) ? msg.elements : [];
  if (!cached) {
    log("TIP_NO_CACHE peer=" + peer + " sender=" + sender);
    return false;
  }
  let changed = false;
  for (const el of elements) {
    if (!el || typeof el !== "object") continue;
    const isGray = el.elementType === 8 || !!el.grayTipElement;
    if (!isGray) continue;
    const text = elementContent(el);
    if (!text || !RECALL_TIP_RE.test(text)) continue;
    const suffix = cached.text ? "（已拦截，原文：" + String(cached.text).slice(0, 300) + "）" : "（已拦截）";
    if (typeof el.content === "string" && el.content) { el.content = text + suffix; changed = true; }
    if (el.grayTipElement && typeof el.grayTipElement.content === "string" && el.grayTipElement.content) { el.grayTipElement.content = el.grayTipElement.content + suffix; changed = true; }
  }
  if (changed) log("REWRITE_TIP peer=" + peer + " text=" + String(cached.text).slice(0, 60));
  return changed;
}

function handleMessage(msg) {
  if (!msg || typeof msg !== "object" || !Array.isArray(msg.elements)) return;
  const tip = isRecallTip(msg);
  if (tip) {
    if (restoreMessage(msg)) return;
    rewriteTip(msg);
    return;
  }
  remember(msg);
}

function walkMsgLists(node, depth, seen) {
  if (!node || typeof node !== "object" || depth > 8) return;
  if (seen.has(node)) return;
  seen.add(node);
  if (Array.isArray(node)) {
    if (node.length && node[0] && typeof node[0] === "object" && Array.isArray(node[0].elements)) {
      for (const msg of node) handleMessage(msg);
    }
    for (const item of node) walkMsgLists(item, depth + 1, seen);
    return;
  }
  for (const key of Object.keys(node)) walkMsgLists(node[key], depth + 1, seen);
}

const stats = { events: 0, recallTips: 0, restored: 0, rewritten: 0, missed: 0 };

function processPayload(payload) {
  if (!payload || typeof payload !== "object") return;
  const seen = new Set();
  walkMsgLists(payload, 0, seen);
}

function processArgs(channel, args) {
  if (!/RM_IPCFROM_MAIN/.test(String(channel))) return;
  let payload = args.length >= 3 && args[2] !== undefined && args[2] !== null ? args[2] : args[1];
  if (typeof payload === "string") {
    try { payload = JSON.parse(payload); } catch (e) { return; }
  }
  if (!payload || typeof payload !== "object") return;
  stats.events += 1;
  processPayload(payload);
  if (payload.msgRecord) handleMessage(payload.msgRecord);
}

module.exports = { processArgs: processArgs, processPayload: processPayload, handleMessage: handleMessage, stats: function () { return stats; } };
`;
